// Wallpapers bundled with the extension (work offline). The four SVGs are generated by
// scripts/make-wallpapers.mjs; the meadow illustration is the official SBC website artwork.
import aurora from './assets/wallpapers/aurora.svg';
import ocean from './assets/wallpapers/ocean.svg';
import emerald from './assets/wallpapers/emerald.svg';
import ember from './assets/wallpapers/ember.svg';
import meadow from './assets/wallpapers/meadow.jpg';

export const WALLPAPERS = [
  { id: 'aurora', url: aurora, base: '#0c0619' },
  { id: 'ocean', url: ocean, base: '#06132a' },
  { id: 'emerald', url: emerald, base: '#041512' },
  { id: 'ember', url: ember, base: '#13060b' },
  { id: 'meadow', url: meadow, base: '#3d5a7a', photo: true },
];

export const wallpaperById = id => WALLPAPERS.find(w => w.id === id) || WALLPAPERS[0];

export function stepWallpaper(id, step) {
  const i = WALLPAPERS.findIndex(w => w.id === id);
  return WALLPAPERS[(Math.max(i, 0) + step + WALLPAPERS.length) % WALLPAPERS.length].id;
}
